+        if (count(self::reports('', 'draft')) >= self::MAX_DRAFTS) {
+            return new WP_Error(
+                'wpallstars_report_full',
+                sprintf(
+                    /* translators: %d: number of drafts. */
+                    __('There are already %d draft reports waiting for review. Send or delete some in Tools → Report a problem first.', 'seoprostack'),
+                    self::MAX_DRAFTS
+                )
