+            $id = strtolower(wp_generate_password(10, false, false));
+        } while (isset($reports[$id]));
+        $now          = time();
+        $reports[$id] = array_merge($fields, array(
+            'id'      => $id,
+            'status'  => 'draft',
+            'source'  => 'administrator' === $source ? 'administrator' : 'assistant',
+            'created' => $now,
+            'updated' => $now,
+            'sent'    => 0,
+            'sent_by' => 0,
