+    public static function update($id, array $input) {
+        $reports = self::all();
+        $id      = sanitize_key((string) $id);
+        if (!isset($reports[$id])) {
+            return new WP_Error('wpallstars_report_missing', __('That report no longer exists.', 'seoprostack'));
+        }
+        if ('draft' !== $reports[$id]['status']) {
+            return new WP_Error('wpallstars_report_sent', __('That report has been sent already.', 'seoprostack'));
